  "dashboard.centro.nas.copia.nube.protege": { es: "lo mismo que la recomendada, y sirve aunque los discos estén por red; más control sobre qué se copia.", en: "the same as the recommended one, and it works even if the disks are network-attached; more control over what's copied." },
  "dashboard.centro.nas.copia.nube.ojo": { es: "cuesta más de 20 veces lo que cuesta la recomendada al año.", en: "it costs more than 20 times the recommended option per year." },
  "dashboard.centro.nas.copia.frio.titulo": { es: "Archivo frío (Amazon Glacier Deep Archive)", en: "Cold archive (Amazon Glacier Deep Archive)" },
  "dashboard.centro.nas.copia.frio.costo": { es: "≈ US$1 por TB al mes · hoy ~US$35 al mes", en: "≈ US$1 per TB per month · ~US$35 a month today" },
  "dashboard.centro.nas.copia.frio.protege": { es: "un desastre grande, como último recurso.", en: "a major disaster, as a last resort." },
  "dashboard.centro.nas.copia.frio.ojo": { es: "recuperar tarda de 12 a 48 horas y bajarlo todo cuesta miles de dólares. Es para guardar, no para recuperar rápido.", en: "restoring takes 12 to 48 hours and downloading everything costs thousands of dollars. It's for keeping, not for quick recovery." },
  "dashboard.centro.nas.copia.miRecomendacion": { es: "Mi recomendación", en: "Recommendation" },
  "dashboard.centro.nas.copia.recomendacionTexto": { es: "Backblaze en la mini como copia principal (≈ US$99 al año: cubre robo, incendio, agua y discos dañados) y, cuando se pueda, el espejo en la oficina para recuperar en horas si un disco se muere. Juntas cumplen la regla 3-2-1 por menos de lo que cuesta un solo mes de la nube por TB.", en: "Backblaze on the mini as the main copy (≈ US$99 a year: covers theft, fire, water and failed disks) and, when possible, the office mirror to recover in hours if a disk dies. Together they meet the 3-2-1 rule for less than a single month of pay-per-TB cloud." },
  "dashboard.centro.nas.copia.paraArrancar": { es: "Para arrancar", en: "To get started" },
  "dashboard.centro.nas.copia.paso1": { es: "Tú: crear la cuenta de Backblaze (Computer Backup) y pagarla; eso no se puede hacer desde Maven.", en: "You: create the Backblaze account (Computer Backup) and pay for it; that can't be done from Maven." },
  "dashboard.centro.nas.copia.paso2": { es: "En la oficina: instalar la app de Backblaze en la mini5, incluir los discos NAS1 y NAS2 y tocar «Permitir» en la pantalla cuando lo pida.", en: "At the office: install the Backblaze app on mini5, include the NAS1 and NAS2 disks and tap «Allow» on screen when asked." },
  "dashboard.centro.nas.copia.paso3": { es: "Maven: mostrar en esta pestaña si la copia está al día y avisar si se atrasa.", en: "Maven: show on this tab whether the copy is up to date and alert if it falls behind." },
