  "dashboard.centro.nas.ficha.titulo": { es: "Ficha del NAS", en: "NAS fact sheet" },
  "dashboard.centro.nas.ficha.respaldoTitulo": { es: "Hoy no hay copia de seguridad", en: "There is no backup today" },
  "dashboard.centro.nas.ficha.respaldoTexto": { es: "Cada archivo existe una sola vez, en NAS1 o en NAS2 (decisión del 28/09/2026). Si un disco se daña, lo que tenga se pierde. Conviene planear una copia: otro disco o la nube.", en: "Each file exists only once, on NAS1 or NAS2 (decision of 09/28/2026). If a disk fails, what it holds is lost. A copy should be planned: another disk or the cloud." },
  "dashboard.centro.nas.ficha.caido": { es: "El NAS está caído desde {desde}", en: "The NAS has been down since {desde}" },
  "dashboard.centro.nas.ficha.arriba": { es: "El NAS está funcionando (última revisión: {cuando})", en: "The NAS is working (last check: {cuando})" },
